const TABLE: Partial<Record<Language, Map<string, string>>> = {};
const LANG_INDEX: Record<Exclude<Language, "en">, number> = { th: 1, es: 2, fr: 3, de: 4, ja: 5, ko: 6, zh: 7 };
for (const row of ROWS) {
  for (const lang of Object.keys(LANG_INDEX) as Exclude<Language, "en">[]) {
    const value = row[LANG_INDEX[lang]];
    if (!value || value === row[0]) continue;
    let map = TABLE[lang];
    if (!map) TABLE[lang] = map = new Map();
    if (!map.has(row[0])) map.set(row[0], value);
  }
}

/**
 * Translate one English interface string. Returns undefined when nothing in
 * the shared table matches, so the caller can fall back to other dictionaries.
 */
export function lookupInterface(text: string, lang: Language): string | undefined {
  if (lang === "en") return undefined;
  const key = text.trim();
  if (!key) return undefined;
  const hit = TABLE[lang]?.get(key);
  if (hit) return hit;
  for (const [re, build] of PATTERNS) {
    const m = key.match(re);
    if (!m) continue;
    const out = build(m)[lang];
    if (out) return out;
  }
  return undefined;
}
